import { CustomTooltip } from 'components/CustomTooltip';
import { Icon, Info } from 'components/icon';
import { Heading } from 'components/UI';
import { StyledTooltip } from 'shared/Styles/typography.styles';

import {
  StyledContentCardHeader,
  StyledMainContainer,
} from './ContentCard.styles';

interface ContentCardProps {
  title: string;
  tooltip?: string;
  children: React.ReactNode;
  fullWidth?: boolean;
  noPaddingX?: boolean;
}

export const ContentCard: React.FC<ContentCardProps> = ({
  title,
  tooltip,
  children,
  fullWidth: useFullWidth = false,
  noPaddingX: useNoPaddingX = false,
}) => {
  return (
    <StyledMainContainer $fullWidth={useFullWidth} $noPaddingX={useNoPaddingX}>
      <StyledContentCardHeader>
        <Heading size="H2">{title}</Heading>
        {tooltip && (
          <CustomTooltip
            content={<StyledTooltip size="small">{tooltip}</StyledTooltip>}
          >
            <Icon icon={Info} size="medium" />
          </CustomTooltip>
        )}
      </StyledContentCardHeader>
      {children}
    </StyledMainContainer>
  );
};
